import os
from typing import Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class SecretRetrievalError(RuntimeError):
    pass


def fetch_api_key(secret_id: Optional[str] = None, region_name: Optional[str] = None) -> str:
    """
    Fetch an API key from AWS Secrets Manager.

    Environment variables used:
      - AWS_SECRET_ID or SECRET_ID: the secret name/ARN
      - AWS_REGION or AWS_DEFAULT_REGION: AWS region

    Returns:
      The secret string value.
    """
    secret_id = secret_id or os.getenv("AWS_SECRET_ID") or os.getenv("SECRET_ID")
    if not secret_id:
        raise SecretRetrievalError(
            "Missing secret identifier. Set AWS_SECRET_ID or SECRET_ID."
        )

    region_name = region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION")
    if not region_name:
        raise SecretRetrievalError(
            "Missing AWS region. Set AWS_REGION or AWS_DEFAULT_REGION."
        )

    client = boto3.client("secretsmanager", region_name=region_name)

    try:
        response = client.get_secret_value(SecretId=secret_id)
    except (ClientError, BotoCoreError) as exc:
        raise SecretRetrievalError(f"Failed to fetch secret '{secret_id}': {exc}") from exc

    secret_string = response.get("SecretString")
    if secret_string is not None:
        return secret_string

    secret_binary = response.get("SecretBinary")
    if secret_binary is not None:
        if isinstance(secret_binary, bytes):
            return secret_binary.decode("utf-8")
        return secret_binary

    raise SecretRetrievalError(f"Secret '{secret_id}' did not contain a retrievable value.")
